import {readDemoPhoto} from './demo-photo.js?v=20261027-3';
import {createDemo,initialDraft,validateDraft} from './staff-demo-model.js?v=20261027-4';
import {scheduleDraft,scheduleFields,bindSchedule,scheduleLabel,lifecycle,publicPosts,staffPosts,NO_EXPIRY_NOTE} from './schedule.js?v=20261027-4';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function mountDemo(root,{readPhoto=readDemoPhoto}={}){
 const model=createDemo();let draft=initialDraft(),timing=scheduleDraft(),editing=null,preview=false,status='',readSchedule,photoToken=0,busy=false,disposed=false,simulated=false,clock=Date.now(),last='';
 const $=s=>root.querySelector(s),focus=s=>$(s)?.focus();
 function card(p,actions=false){const state=lifecycle(p,clock),ended=['ended','soldout'].includes(state);return '<article class="demo-card '+(ended?'demo-ended':'')+'">'+(ended?'<div class="demo-ended-overlay">終了しました</div>':'')+'<img src="'+p.image+'" alt="選んだ写真"><div class="demo-card-content"><span class="demo-badge '+(ended?'ended':'')+'">'+(state==='scheduled'?'予約中（お客さんには非表示）':ended?'終了しました':'掲載中（練習）')+'</span><h3>'+esc(p.title)+'</h3><p class="demo-body">'+esc(p.text)+'</p><p class="demo-small">'+esc(scheduleLabel(p))+'</p>'+(!p.end?'<small>'+NO_EXPIRY_NOTE+'</small>':'')+(actions?'<div class="actions"><button class="quiet" data-edit="'+p.id+'">編集する</button><button class="quiet" data-end="'+p.id+'" '+(ended?'disabled':'')+'>終了にする</button></div>':'')+'</div></article>';}
 function capture(){draft={...draft,title:$('#demo-title').value,text:$('#demo-text').value,...readSchedule()};}
 function fresh(){photoToken++;busy=false;draft=initialDraft();timing=scheduleDraft();editing=null;preview=false;}
 function render(target){if(disposed)return;const posts=staffPosts(model.list(),clock);last=posts.map(p=>lifecycle(p,clock)).join();
 root.innerHTML='<p class="demo-status" role="status" aria-live="polite">'+esc(status)+'</p><div class="demo-grid"><section class="demo-panel" aria-labelledby="compose-heading"><h2 id="compose-heading" tabindex="-1">'+(preview?'この内容で試しますか？':editing?'練習の投稿を編集':'写真から投稿を試す')+'</h2>'+(preview?card({...draft,state:'active'})+'<p>練習用です。お店のページには公開されません。</p><div class="actions"><button id="demo-publish">デモ投稿する</button><button id="demo-back" class="quiet">内容に戻る</button></div>':'<form id="demo-form" novalidate><p class="demo-small">まず写真を撮るか、端末の写真を選んでください。</p><input id="demo-camera" type="file" accept="image/jpeg,image/png,image/webp" capture="environment" hidden><input id="demo-library" type="file" accept="image/jpeg,image/png,image/webp" hidden><div class="photo-actions"><button type="button" id="demo-take-photo">撮影する</button><button type="button" id="demo-choose-photo" class="quiet">写真を選ぶ</button></div>'+(draft.image?'<img class="sample-thumb" src="'+draft.image+'" alt="選んだ写真">':'')+'<p class="demo-small">写真は送信されません。撮影できない場合は「写真を選ぶ」を使ってください。JPEG・PNG・WebP、10MBまで。</p><label for="demo-title">見出し（必須・40文字まで）</label><input id="demo-title" maxlength="40" required value="'+esc(draft.title)+'" aria-describedby="demo-error"><label for="demo-text">本文（必須・180文字まで）</label><textarea id="demo-text" maxlength="180" required aria-describedby="demo-error">'+esc(draft.text)+'</textarea>'+scheduleFields(timing)+'<button type="submit">見え方を確認する →</button></form>')+'<p id="demo-error" role="alert"></p></section><section class="demo-panel" aria-labelledby="list-heading"><h2 id="list-heading" tabindex="-1">練習の投稿一覧</h2><p class="demo-small">この画面だけに表示します（'+posts.length+' / 5件）。</p>'+(posts.length?posts.map(p=>card(p,true)).join(''):'<p>まだ投稿はありません。</p>')+'<button id="demo-new" class="quiet">新しい投稿を試す</button><button id="demo-reset" class="quiet">デモを最初からやり直す</button><div class="reset-confirm" hidden><p>この画面の写真・入力・練習の投稿を消しますか？</p><button id="reset-yes">最初に戻す</button><button id="reset-no" class="quiet">戻さない</button></div><section class="demo-customer"><h3>お客さまの表示（練習）</h3><p class="demo-small">確認時刻：'+new Date(clock).toLocaleString('ja-JP',{timeZone:'Asia/Tokyo'})+'（日本時間）</p><div class="actions"><button id="clock-now" class="quiet">現在時刻</button><button id="clock-start" class="quiet">開始時刻を試す</button><button id="clock-end" class="quiet">終了時刻を試す</button></div>'+publicPosts(posts,clock).map(p=>card(p)).join('')+'</section></section></div>';
 if(!preview){readSchedule=bindSchedule(root,timing);$('#demo-form').onsubmit=e=>{e.preventDefault();if(busy)return;try{capture();draft=validateDraft(draft);preview=true;status='';render('#compose-heading');}catch(e){$('#demo-error').textContent=e.message;focus(!draft.image?'#demo-choose-photo':!draft.title.trim()?'#demo-title':'#demo-text');}};
 $('#demo-take-photo').onclick=()=>$('#demo-camera').click();$('#demo-choose-photo').onclick=()=>$('#demo-library').click();
 const choose=async e=>{const file=e.target.files?.[0];if(!file)return;const token=++photoToken;busy=true;draft.title=$('#demo-title').value;draft.text=$('#demo-text').value;for(const b of root.querySelectorAll('#demo-form button'))b.disabled=true;$('#demo-error').textContent='写真を準備しています…';try{const image=await readPhoto(file);if(disposed||token!==photoToken)return;draft.image=image;draft.photo='local';busy=false;render('#compose-heading');}catch(e){if(!disposed&&token===photoToken){busy=false;$('#demo-error').textContent=e.message;for(const b of root.querySelectorAll('#demo-form button'))b.disabled=false;}}};$('#demo-camera').onchange=choose;$('#demo-library').onchange=choose;
 }else{$('#demo-back').onclick=()=>{preview=false;render('#compose-heading');};$('#demo-publish').onclick=()=>{if(busy)return;busy=true;try{model.save(draft,editing);fresh();status='練習の投稿を保存しました。お店のページには公開されません。';render('#list-heading');}catch(e){busy=false;$('#demo-error').textContent=e.message;}};}
 for(const b of root.querySelectorAll('[data-edit]'))b.onclick=()=>{photoToken++;busy=false;editing=Number(b.dataset.edit);draft=model.list().find(p=>p.id===editing);timing=scheduleDraft(draft);preview=false;status='';render('#compose-heading');};
 for(const b of root.querySelectorAll('[data-end]'))b.onclick=()=>{model.end(Number(b.dataset.end));status='練習の投稿を終了表示にしました。';render('#list-heading');};
 $('#demo-new').onclick=()=>{fresh();status='';render('#compose-heading');};$('#demo-reset').onclick=()=>{$('.reset-confirm').hidden=false;focus('#reset-no');};$('#reset-no').onclick=()=>{$('.reset-confirm').hidden=true;focus('#demo-reset');};$('#reset-yes').onclick=()=>{model.reset();fresh();status='写真と入力を消して最初に戻しました。';render('#compose-heading');};
 for(const [id,key] of [['clock-start','start'],['clock-end','end']])$('#'+id).onclick=()=>{const p=posts.find(p=>p[key]);if(p){clock=Date.parse(p[key]);simulated=true;render('#list-heading');}};
 $('#clock-now').onclick=()=>{simulated=false;clock=Date.now();render('#list-heading');};if(target)focus(target);
 }
 const timer=setInterval(()=>{if(disposed||simulated||busy||$('.reset-confirm')?.hidden===false)return;clock=Date.now();const next=model.list().map(p=>lifecycle(p,clock)).join();if(next===last)return;if(!preview){draft.title=$('#demo-title').value;draft.text=$('#demo-text').value;try{Object.assign(draft,readSchedule());}catch{}}const id=root.ownerDocument.activeElement?.id;render(id?'#'+id:null);},1000);timer.unref?.();
 render();return ()=>{disposed=true;photoToken++;clearInterval(timer);model.reset();draft=initialDraft();root.replaceChildren();};
}
if(typeof document!=='undefined'){const root=document.querySelector('#demo-workspace');if(root)mountDemo(root);}
